from sqlalchemy.orm import Session

from app.models import Chunk


def save_chunks(db: Session, document_id, chunks):
    db_chunks = []

    for chunk in chunks:
        db_chunk = Chunk(
            document_id=document_id,
            chunk_index=chunk["chunk_index"],
            page_number=chunk["page_number"],
            content=chunk["text"]
        )

        db_chunks.append(db_chunk)

    db.add_all(db_chunks)
    db.commit()

    return len(db_chunks)

# Takes the chunks generated by our chunking service and saves them in the document_chunks table, linked to their original PDF.